#!/usr/bin/env python3
import os, json, sys, math, random

# Physical constants (SI)
G = 6.67430e-11          # m^3 kg^-1 s^-2
c = 2.99792458e8        # m s^-1
hbar = 1.054571817e-34  # J s
k_B = 1.380649e-23      # J K^-1
M_sun = 1.98847e30      # kg

def schwarzschild_radius(M):
    return 2 * G * M / c**2

def isco_radius(M, a=0.0):
    # prograde ISCO radius in meters (Bardeen et al. 1972)
    Z1 = 1 + (1 - a**2)**(1/3) * ((1 + a)**(1/3) + (1 - a)**(1/3))
    Z2 = math.sqrt(3 * a**2 + Z1**2)
    if a >= 0:
        r_isco = M * (3 + Z2 - math.sqrt((3 - Z1)*(3 + Z1 + 2*Z2)))
    else:
        r_isco = M * (3 + Z2 + math.sqrt((3 - Z1)*(3 + Z1 + 2*Z2)))
    return r_isco

def horizon_area(r_s):
    return 4 * math.pi * r_s**2

def photon_sphere_radius(M, a=0.0):
    # radius of the unstable photon orbit (meters)
    Z1 = 1 + (1 - a**2)**(1/3) * ((1 + a)**(1/3) + (1 - a)**(1/3))
    Z2 = math.sqrt(3 * a**2 + Z1**2)
    if a >= 0:
        r_ph = M * (3 + Z2 - math.sqrt((3 - Z1)*(3 + Z1 + 2*Z2)))
    else:
        r_ph = M * (3 + Z2 + math.sqrt((3 - Z1)*(3 + Z1 + 2*Z2)))
    return r_ph

def angular_velocity_isco(M, r_isco):
    # orbital angular frequency at the ISCO (rad s^-1)
    return math.sqrt(G * M / r_isco**3)

def angular_velocity_photon(M, r_ph):
    return math.sqrt(G * M / r_ph**3)

def critical_impact_parameter(M, impact_param):
    # impact parameter that yields a marginally bound orbit
    return impact_param / (1 - impact_param/M)

def test_hypothesis(M_bh):
    r_s = schwarzschild_radius(M_bh)
    r_isco = isco_radius(M_bh)
    r_ph = photon_sphere_radius(M_bh)
    omega_isco = angular_velocity_isco(M_bh, r_isco)
    omega_ph = angular_velocity_photon(M_bh, r_ph)
    b_crit = critical_impact_parameter(M_bh, impact_param=2 * r_ph)
    area = horizon_area(r_s)
    print(f"Schwarzschild radius (r_s): {r_s:.3e} m")
    print(f"ISCO radius (r_isco): {r_isco:.3e} m")
    print(f"Photon sphere radius (r_ph): {r_ph:.3e} m")
    print(f"Angular frequency at ISCO (omega_isco): {omega_isco:.3e} rad/s")
    print(f"Angular frequency at photon sphere (omega_ph): {omega_ph:.3e} rad/s")
    print(f"Critical impact parameter (b_crit): {b_crit:.3e} m")
    print(f"Horizon area (A): {area:.3e} m^2")
    # Consistency checks
    rel_err_isco = abs(omega_isco - omega_ph) / omega_isco
    rel_err_area = (area - (4 * math.pi * r_s**2)) / (4 * math.pi * r_s**2)
    if rel_err_isco > 1e-2 or rel_err_area > 1e-2:
        print("FAIL: At least one dimensionful relation deviates >1%."), None
    else:
        print("PASS: All dimensionful relations within 1%.")

if __name__ == "__main__":
    # Example: test with a 10 solar‑mass black hole
    test_hypothesis(10 * M_sun)
